\centering
\small
\caption{In-distribution 4-class depth estimation accuracy (\%) across 3 model families $\times$ 3 decoding strategies. RF classifier with 19 statistical features, 5-fold CV (std 0.2--0.9pp across all cells). Chance = 25\%.}
\label{tab:main_matrix}
\begin{tabular}{lccc}
\toprule
Model & Nucleus & Temp & Top-$k$ \\
 & $p{=}0.95$ & $\tau{=}0.9$ & $k{=}50$ \\
\midrule
Pythia-1.4B & 78.2 & 76.3 & 69.6 \\
OLMo-1B & 78.8 & 82.0 & 74.2 \\
GPT-2 XL & 83.3 & \textbf{85.4} & 76.6 \\
